        r = self.rng
        out = []
        while len(out) < stop:
            choice = r.random()
            if counter is not None and choice < 0.25:
                # emit side effect
                name = self.fresh("e")
                out.append(let(name, "int", call("emit", [self.expr("int", scope, 1)])))
                self.emits += 1
            elif choice < 0.45:
                typ = r.choice(["int", "int", "bool"])
                name = self.fresh(typ[0])
                out.append(let(name, typ, self.expr(typ, scope, r.randrange(0, depth+1))))
                scope.declare(name, typ)
            elif choice < 0.60:
                targets = [n for n, t in scope.visible()
                           if n != counter and (counter is None or True)]
                if targets:
                    nm, ty = r.choice(targets)
                    out.append(assign(nm, self.expr(ty, scope, depth)))
            elif choice < 0.78 and depth >= 1:
                if r.random() < 0.3:
                    self.constbranch += 1
                    cond = compare("lt", int_(1), int_(2))  # constant true
                else:
                    cond = self.expr("bool", scope, depth-1)
                thn = self.stmts(scope.child(), depth-1, r.randrange(0, 3), counter)
                els = self.stmts(scope.child(), depth-1, r.randrange(0, 3), counter)
                out.append(if_(cond, thn, els))
            elif choice < 0.90 and depth >= 1:
                # shadow block
                cand = [n for n, t in scope.visible() if n != counter and t == "int"]
                if cand:
                    nm = r.choice(cand)
                    inner = scope.child()
                    body = [let(nm, "int", self.expr("int", inner, 1))]
                    body += self.stmts(inner, depth-1, r.randrange(0, 2), counter)
                    out.append(block(body))
                    self.shadows += 1
                else:
                    out.append(let(self.fresh("i"), "int", int_(r.randrange(0, 3))))
            else:
                name = self.fresh("h")
                out.append(let(name, "int", call("emit", [int_(r.randrange(0, 9))])))
                self.emits += 1
        return out

    def loop_stmt(self, scope, depth):
        r = self.rng
        counter = self.fresh("ctr")
        bound = r.randrange(0, 4)
        scope.declare(counter, "int")
        body = []
        # junk invariant: constant pure chain inside the loop
        if r.random() < 0.7:
            body.append(let(self.fresh("junk"), "int",
                            arith("add", arith("add", int_(2), int_(3)), int_(4))))
        nstm = r.randrange(1, 3)
        body += self.stmts(scope, depth, nstm, counter=counter)
        # real loop-varying accumulation read by something side-effecting
        body.append(let(self.fresh("step"), "int",
                        call("emit", [arith("add", var(counter), int_(0))])))
        self.emits += 1
        body.append(assign(counter, arith("add", var(counter), int_(1))))
        self.loops += 1
        return while_(compare("lt", var(counter), int_(bound)), body)

    def program(self):
        r = self.rng
        funcs = [func("emit", [param("v", "int")], "int", [ret(var("v"))])]
        nhelpers = r.randrange(0, 3)
        for i in range(nhelpers):
            p = self.fresh("x")
            funcs.insert(1 + i, func(self.fresh("h"), [param(p, "int")], "int", [
                let(self.fresh("y"), "int", arith("add", int_(1), int_(2))),
                ret(arith("add", var(p), int_(0))),
            ]))
            self.helpers += 1

        params = [param("n", "int")]
        if r.random() < 0.7:
            params.append(param("c", "bool"))
        if r.random() < 0.5:
            params.append(param("m", "int"))

        scope = Scope()
        for p in params:
            scope.declare(p["name"], p["type"])
        body = []
        nblocks = r.randrange(2, 5)
        depth = 2
        for _ in range(nblocks):
            if r.random() < 0.6:
                body.append(self.loop_stmt(scope, depth))
            else:
                body += self.stmts(scope, depth, r.randrange(1, 3))
        ret_expr = self.expr("int", scope, 1)
        body.append(let(self.fresh("out"), "int", call("emit", [ret_expr])))
        self.emits += 1
        body.append(ret(var(body[-1]["name"])))
        main = func("main", params, "int", body)
        return program(main, *funcs)


class Scope:
    def __init__(self, parent=None):
        self.parent = parent
        self.d = {}
    def declare(self, n, t):
        if n in self.d:
            raise AssertionError("dup")
        self.d[n] = t
    def child(self):
        return Scope(self)
    def visible(self):
        items = []
        s = self
        while s is not None:
            for n, t in s.d.items():
                if not any(n == x[0] for x in items):
                    items.append((n, t))
            s = s.parent
        return items


if __name__ == "__main__":
    stats = {"loops": 0, "shadows": 0, "constbranch": 0, "helpers": 0, "emits": 0, "calls": 0}
